## 2. 安装 puppeteer-core（装到临时目录，勿污染交付目录）
```powershell
$tools = "$env:TEMP\docform-tools"
New-Item -ItemType Directory -Force $tools | Out-Null
Set-Location $tools
npm init -y
npm i puppeteer-core --no-audit --no-fund
```
若 npm 安装失败（无网络等），走【降级路径】（见第 5 步）。

## 3. 写测试脚本
把下面内容**原样**写入 "$env:TEMP\docform-tools\test.js"（UTF-8）：

```js
const puppeteer = require('puppeteer-core');
const fs = require('fs');
const OUT = 'E:/codex-prj/ab-worktrees/pi-matrix/cell-j08-s08-a/evidence';
const URL = 'file:///E:/codex-prj/ab-worktrees/pi-matrix/cell-j08-s08-a/index.html';
const sleep = ms => new Promise(r => setTimeout(r, ms));

(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const browser = await puppeteer.launch({
    executablePath: process.env.CHROME_PATH,
    headless: true,
    args: ['--no-sandbox', '--disable-gpu', '--force-color-profile=srgb']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1440, height: 900, deviceScaleFactor: 2 });
  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + String(e)));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });

  const report = { url: URL, screenshots: [], assertions: [], pageErrors: errors };
  const shot = async n => { await page.screenshot({ path: OUT + '/' + n }); report.screenshots.push(n); };

  await page.goto(URL, { waitUntil: 'load' });
  await sleep(700);
  report.hookPresent = await page.evaluate(() => !!window.__docform);
  await shot('01-initial-load.png');

  const results = await page.evaluate(() => {
    const out = [];
    const t = (name, ok, detail) => out.push({ name, ok: !!ok, detail: detail == null ? '' : String(detail) });
    const norm = s => s.replace(/\*\*([^*]+)\*\*/g, '$1').replace(/\*([^*]+)\*/g, '$1').replace(/`([^`]+)`/g, '$1');
    const D = window.__docform.state.doc;
    const sec0 = D.sections[0];

    let ok1 = D.sections.length === 5, bad1 = '';
    document.querySelectorAll('.pv-sec').forEach((secEl, si) => {
      const sec = D.sections[si]; if (!sec) { ok1 = false; return; }
      const h2 = secEl.querySelector('.pv-h2').textContent.replace(/^\d+/, '').trim();
      if (h2 !== sec.title.trim()) { ok1 = false; bad1 += 'h2@' + si + ';'; }
      const blocks = secEl.querySelectorAll('.pv-block');
      if (blocks.length !== sec.blocks.length) { ok1 = false; bad1 += 'n@' + si + ';'; return; }
      sec.blocks.forEach((b, bi) => {
        const el = blocks[bi];
        if (b.type === 'p' && el.querySelector('p').textContent !== norm(b.text)) { ok1 = false; bad1 += 'p@' + si + '.' + bi + ';'; }
        if (b.type === 'list') {
          const lis = Array.from(el.querySelectorAll('li'), x => x.textContent).join('\n');
          if (lis !== b.items.map(norm).join('\n')) { ok1 = false; bad1 += 'li@' + si + '.' + bi + ';'; }
        }
        if (b.type === 'callout' && el.querySelector('.co-text').textContent !== norm(b.text)) { ok1 = false; bad1 += 'co@' + si + '.' + bi + ';'; }
      });
    });
    t('T1 首屏预览与文档模型逐块一致', ok1, bad1 || (D.sections.length + ' 节全部匹配'));

    const secTitle = document.querySelector('.sec-title');
    secTitle.value = '背景与目标（修订版）';
    secTitle.dispatchEvent(new Event('input', { bubbles: true }));
    const h2v = document.querySelector('#pv-' + sec0.id + ' .pv-h2').textContent.replace(/^\d+/, '').trim();
    t('T2 编辑小节标题→预览即时一致', h2v === '背景与目标（修订版）', h2v);

    const ta = document.querySelector('.block-card.t-p textarea');
    ta.value = '一致性验证：**结构化编辑**与 `预览` 保持实时同步。';
    ta.dispatchEvent(new Event('input', { bubbles: true }));
    const ptxt = document.querySelector('[data-pv="' + sec0.blocks[0].id + '"] p').textContent;
    t('T3 编辑段落正文→预览即时一致', ptxt === norm(ta.value), ptxt);

    const li0 = document.querySelectorAll('#pv-' + sec0.id + ' li').length;
    Array.from(document.querySelectorAll('.add-row button')).find(b => b.textContent.indexOf('列表') >= 0).click();
    const li1 = document.querySelectorAll('#pv-' + sec0.id + ' li').length;
    t('T4 新增列表块→预览同步出现', li1 === li0 + 2, li0 + '→' + li1);

    const chip0 = document.getElementById('chipText').textContent;
    secTitle.value = '';
    secTitle.dispatchEvent(new Event('input', { bubbles: true }));
    const chip1 = document.getElementById('chipText').textContent;
    t('T5 清空小节标题→结构检查告警', chip0.indexOf('通过') >= 0 && chip1.indexOf('结构问题') >= 0, chip0 + ' → ' + chip1);

    Array.from(document.querySelectorAll('#topbar button')).find(b => b.textContent.indexOf('撤销') >= 0).click();
    const chip2 = document.getElementById('chipText').textContent;
    const h2b = document.querySelector('#pv-' + sec0.id + ' .pv-h2').textContent.replace(/^\d+/, '').trim();
    t('T6 撤销→标题与结构检查复原', chip2.indexOf('通过') >= 0 && h2b === '背景与目标（修订版）', 'chip=' + chip2 + ' h2=' + h2b);

    const md = window.__docform.docToMarkdown(D);
    const html = window.__docform.docToHTML(D);
    window.__md = md;
    t('T7 导出Markdown/HTML含完整结构', md.indexOf('# ') === 0 && md.indexOf('## 1.') > 0 && html.indexOf('<h1>') > 0, md.split('\n')[0]);

    t('T8 同步徽标回到已同步', document.getElementById('syncText').textContent.indexOf('已同步') >= 0, document.getElementById('syncText').textContent);
    return out;
  });
  report.assertions = results;

  const mdOut = await page.evaluate(() => window.__md || '');
  fs.writeFileSync(OUT + '/export-sample.md', mdOut, 'utf8');

  await sleep(500);
  await shot('02-after-edits.png');

  await page.evaluate(() => {
    const secTitle = document.querySelector('.sec-title');
    secTitle.value = '';
    secTitle.dispatchEvent(new Event('input', { bubbles: true }));
    document.getElementById('chip').click();
  });
  await sleep(400);
  await shot('03-structure-check.png');

  await page.goto(URL, { waitUntil: 'load' });
  await sleep(700);
  await shot('04-reload-restored.png');
  report.restored = await page.evaluate(() => ({
    titleValue: (document.querySelector('.doc-title') || {}).value || null,
    stSave: document.getElementById('stSave').textContent
  }));

  fs.writeFileSync(OUT + '/test-results.json', JSON.stringify(report, null, 2), 'utf8');
  await browser.close();
  const pass = report.assertions.filter(a => a.ok).length;
  console.log('HOOK=' + report.hookPresent + ' PASS=' + pass + '/' + report.assertions.length + ' SHOTS=' + report.screenshots.length + ' JSERRORS=' + errors.length);
  report.assertions.forEach(a => console.log((a.ok ? 'OK  ' : 'FAIL') + ' | ' + a.name + ' | ' + a.detail));
  process.exit(pass === report.assertions.length && errors.length === 0 ? 0 : 2);
})().catch(e => { console.error('FATAL ' + (e && e.message)); process.exit(1); });
```

## 4. 运行
```powershell
$env:CHROME_PATH = "<第1步找到的第一个浏览器路径>"
Set-Location "$env:TEMP\docform-tools"
node test.js
```
- 退出码 0 = 全部通过。把 stdout 完整记录。
- 若 launch 报 headless 相关错误，把脚本里 headless:true 改为 headless:'new' 再试一次；再失败则报告错误原文。

