const puppeteer = require('puppeteer-core');
const sleep = ms => new Promise(r => setTimeout(r, ms));

(async () => {
  const browser = await puppeteer.launch({
    executablePath: process.env.CHROME_PATH,
    headless: true,
    args: ['--no-sandbox', '--disable-gpu', '--force-color-profile=srgb']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1440, height: 900, deviceScaleFactor: 2 });
  await page.goto('file:///E:/codex-prj/ab-worktrees/pi-matrix/cell-j08-s08-a/index.html', { waitUntil: 'load' });
  await sleep(700);

  const probe = await page.evaluate(async () => {
    const D = window.__docform.state.doc;
    const issues = window.__docform.collectIssues ? window.__docform.collectIssues(D) : null;
    const r = {};
    r.chipTextInitial = document.getElementById('chipText').textContent;
    r.issuesInitial = issues;
    // 等待同步徽标稳定（最多 6 秒）
    for (let i = 0; i < 30; i++) {
      const s = document.getElementById('syncText').textContent;
